import{_ as a,o as i,a as o,ag as t}from"./chunks/framework.Do1Zayaf.js";const u=JSON.parse('{"title":"Roxie Knowledge Base","description":"","frontmatter":{},"headers":[],"relativePath":"aidoc/roxie-kb/overview.md","filePath":"aidoc/roxie-kb/overview.md","lastUpdated":1779520499000}'),r={name:"aidoc/roxie-kb/overview.md"};function n(s,e,l,c,d,h){return i(),o("div",null,e[0]||(e[0]=[t('<h1 id="roxie-knowledge-base" tabindex="-1">Roxie Knowledge Base <a class="header-anchor" href="#roxie-knowledge-base" aria-label="Permalink to &quot;Roxie Knowledge Base&quot;">​</a></h1><blockquote><p><strong>Note</strong>: This file is maintained by engineers and the <code>Roxie Developer</code> AI agent. It tracks critical facts, high-level architecture, performance bottlenecks, and execution mechanics specifically for the Roxie component.</p></blockquote><hr><h2 id="_1-system-priorities" tabindex="-1">1. System Priorities <a class="header-anchor" href="#_1-system-priorities" aria-label="Permalink to &quot;1. System Priorities&quot;">​</a></h2><p>Roxie is the rapid data delivery engine for the HPCC platform. It supports millions of dollars in revenue so its engineering focus revolves entirely around <strong>reliability</strong> and <strong>performance</strong>.</p><h2 id="_2-memory-management" tabindex="-1">2. Memory Management <a class="header-anchor" href="#_2-memory-management" aria-label="Permalink to &quot;2. Memory Management&quot;">​</a></h2><ul><li><strong>Dual Allocators</strong>: Avoid allocations on critical execution paths to secure predictable latency.</li><li><strong>Custom Memory</strong>: <code>roxie/roxiemem</code> contains a highly specialized memory manager. If making modifications here, consult both inline comments and <code>MemoryManager.md</code>.</li><li><strong>Standard Heap</strong>: For the standard C++ heap (used heavily for structures like indexes, buffers, and temporary strings), the standard system allocator is replaced with <code>jemalloc</code> globally.</li></ul><h2 id="_3-concurrency-contention" tabindex="-1">3. Concurrency &amp; Contention <a class="header-anchor" href="#_3-concurrency-contention" aria-label="Permalink to &quot;3. Concurrency &amp; Contention&quot;">​</a></h2><ul><li><strong>Bottlenecks</strong>: Multi-threading bottlenecks (thread contention, locking) dictate maximum throughput under load.</li><li><strong>jhtree Node Cache Architecture</strong>: The index node cache implementation found in <a href="./../../system/jhtree/jhtree.cpp.html"><code>system/jhtree/jhtree.cpp</code></a> is fiercely optimized. Any change touching it requires extreme scrutiny as it is a major contention point. <ul><li><strong>Subcaching</strong>: To reduce thread contention under heavy query load, the <code>CNodeCache</code> partitions memory across multiple MRU subcaches (<code>cacheBuckets</code>), assigning keys via a shift hash (<code>cacheBits</code>). See <a href="./../../system/jhtree/jhtree.cpp.html"><code>system/jhtree/jhtree.cpp</code></a>.</li><li><strong>Separation of Concerns</strong>: Caching limits are enforced strictly by node type via a three-pronged <code>CacheMax</code> approach: Branches (<code>maxNodeMem</code>), Leaves (<code>maxLeaveMem</code>), and Blobs (<code>maxBlobMem</code>).</li></ul></li></ul><h2 id="_4-query-execution-pipeline" tabindex="-1">4. Query Execution Pipeline <a class="header-anchor" href="#_4-query-execution-pipeline" aria-label="Permalink to &quot;4. Query Execution Pipeline&quot;">​</a></h2><ul><li><strong>Index Reading (I/O)</strong>: Roxie spends &gt;50% of its lifespan searching and reading indexes. Improvements to I/O logic, buffering, caching, or read layout directly drive up overall throughput.</li><li><strong>&quot;Hybrid&quot; Index Processing</strong>: Roxie indexes act mostly in the <code>hybrid</code> format (<code>BlockCompression = 5</code> for leaves, <code>InplaceCompression = 2</code> for branches). This aims to achieve an optimal balance - minimizing disk I/O through block-compressed leaves while retaining fast, in-memory CPU traversal speeds for inplace-compressed branches. See <code>HybridIndexCompressor</code> in <a href="./../../system/jhtree/jhblockcompressed.cpp.html#L391"><code>system/jhtree/jhblockcompressed.cpp</code></a>.</li><li><strong>Activity Choreography</strong>: The way internal server activities interact can be a massive point of friction. Inefficiencies here drag down every query sequentially.</li></ul><h2 id="_5-startup-scaling" tabindex="-1">5. Startup &amp; Scaling <a class="header-anchor" href="#_5-startup-scaling" aria-label="Permalink to &quot;5. Startup &amp; Scaling&quot;">​</a></h2><ul><li><strong>Query Loading</strong>: The methodology by which Roxie loads queries at startup dictates how rapidly dynamic clusters can spin up and scale sideways to meet user demand.</li></ul><h2 id="_6-network-boundaries" tabindex="-1">6. Network Boundaries <a class="header-anchor" href="#_6-network-boundaries" aria-label="Permalink to &quot;6. Network Boundaries&quot;">​</a></h2><ul><li><strong>Worker/Server Communication</strong>: Pushing data between the central Roxie server nodes and Roxie workers impacts latency. Watch cross-chatter closely.</li><li><strong>UDP / TCP Alternatives</strong>: Roxie relies heavily on either UDP (<code>roxie/udplib/</code>) or TCP abstractions (<code>system/security/securesocket/socketutils.hpp</code>) for internal communication, as they are alternatives rather than used alongside each other. Historically, UDP has been used and remains the default for production systems. TCP is believed to have advantages but has not been used in anger in production environments yet.</li></ul><h2 id="_7-detailed-documentation-index" tabindex="-1">7. Detailed Documentation Index <a class="header-anchor" href="#_7-detailed-documentation-index" aria-label="Permalink to &quot;7. Detailed Documentation Index&quot;">​</a></h2><p>For deeper dives into specific architectural areas and to help direct AI agents, refer to the following specialized knowledge base documents:</p><ul><li><a href="./memory.html">Memory Management</a> - Deep dive into <code>roxiemem</code>, caching, and memory limits.</li><li><a href="./networking.html">Networking &amp; Transport</a> - Details on UDP vs TCP, IP multicasting, and messaging.</li><li><a href="./topologies.html">Topologies &amp; Deployment</a> - Constraints for Massively Parallel, Single-VM, and Ephemeral deployments.</li><li><a href="./server-logic.html">Server Logic &amp; Flow</a> - Core Roxie server mechanics and query dispatching.</li><li><a href="./worker-activities.html">Worker Activities</a> - Execution nodes and graph execution inside workers.</li><li><a href="./server-to-worker.html">Server-to-Worker Communication</a> - Request dispatching mechanism and packet management.</li><li><a href="./worker-to-server.html">Worker-to-Server Communication</a> - Results routing and telemetry back to the server.</li><li><a href="./query-invariants-and-parsing.html">Query Invariants and Parsing</a> - Pre-execution parsing and subgraph preparation.</li><li><a href="./startup-and-config.html">Startup &amp; Configuration</a> - Initial query loading, dynamic topology, and hot-swapping.</li><li><a href="./parallel-execution.html">Parallel Execution</a> - Multi-threading, strands, and contention optimization.</li><li><a href="./keyed-joins.html">Keyed Joins &amp; Splitters</a> - Specific optimization characteristics for distributed joins and data correlation.</li><li><a href="./optimizations.html">Optimizations Backlog</a> - The main repository for all architectural bottlenecks, proposed fixes, and ongoing investigations.</li></ul>',18)]))}const p=a(r,[["render",n]]);export{u as __pageData,p as default};
